import { useEffect, useMemo, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import {
  Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, Legend, Line, LineChart,
  Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis
} from 'recharts';
import {
  Activity, AlertTriangle, ArrowDownRight, ArrowRight, ArrowUpRight, Bell,
  BrainCircuit, CheckCircle2, ChevronDown, CircleAlert, Download, FileDown,
  FileUp, Lightbulb, LayoutDashboard, Menu, MessageSquareText, Plus,
  RefreshCw, ScanEye, Search, Settings2, ShieldCheck, SlidersHorizontal, Pencil, Trash2,
  Sparkles, Store, TrendingUp, Wallet, X, Zap
} from 'lucide-react';
import { apiDelete, apiDownload, apiGet, apiPatch, apiPost, apiPut, apiUpload } from './services/api';
import { transactions as demoRows, type Transaction } from './data/demo';

type Page = 'Overview'|'Transactions'|'Revenue intelligence'|'Expense intelligence'|'Data quality'|'Leak detection'|'Anomaly intelligence'|'Forecasting'|'Business health'|'Recommendations'|'What-if simulator'|'Vendor intelligence'|'Subscription intelligence'|'Alerts centre'|'AI assistant'|'Reports'|'Settings';
type State = { overview:any; transactions:any[]; expenses:any; revenue:any; comparison:any; budgets:any; quality:any; leaks:any[]; anomalies:any; forecast:any; health:any; recommendations:any[]; vendors:any[]; subscriptions:any[]; alerts:any[] };
const NAV: {label:Page;icon:any;group:string}[] = [
  {label:'Overview',icon:LayoutDashboard,group:'WORKSPACE'}, {label:'Transactions',icon:Wallet,group:'WORKSPACE'}, {label:'Revenue intelligence',icon:ArrowUpRight,group:'WORKSPACE'},
  {label:'Expense intelligence',icon:Activity,group:'INTELLIGENCE'}, {label:'Leak detection',icon:ScanEye,group:'INTELLIGENCE'},
  {label:'Anomaly intelligence',icon:BrainCircuit,group:'INTELLIGENCE'}, {label:'Forecasting',icon:ArrowUpRight,group:'INTELLIGENCE'},
  {label:'Business health',icon:ShieldCheck,group:'INTELLIGENCE'}, {label:'Recommendations',icon:Lightbulb,group:'INTELLIGENCE'},
  {label:'What-if simulator',icon:SlidersHorizontal,group:'INTELLIGENCE'}, {label:'Vendor intelligence',icon:Store,group:'INTELLIGENCE'},
  {label:'Subscription intelligence',icon:RefreshCw,group:'INTELLIGENCE'}, {label:'Alerts centre',icon:Bell,group:'MANAGE'},
  {label:'AI assistant',icon:MessageSquareText,group:'MANAGE'}, {label:'Reports',icon:FileDown,group:'MANAGE'},
  {label:'Data quality',icon:ShieldCheck,group:'MANAGE'}, {label:'Settings',icon:Settings2,group:'MANAGE'}
];
const EMPTY: State = {overview:null,transactions:demoRows,expenses:null,revenue:null,comparison:null,budgets:null,quality:null,leaks:[],anomalies:null,forecast:null,health:null,recommendations:[],vendors:[],subscriptions:[],alerts:[]};
const fmt = (value:number,currency='USD') => {
  try { return new Intl.NumberFormat('en-US',{style:'currency',currency,maximumFractionDigits:0}).format(value || 0); }
  catch { return (value || 0).toLocaleString(); }
};
const shortNumber = (n:number) => new Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:1}).format(n || 0);
const statusText = (status:string) => status === 'resolved' ? 'Resolved' : status === 'dismissed' ? 'Dismissed' : status === 'reviewed' ? 'Reviewed' : 'Open';

export default function App() {
  const [page,setPage] = useState<Page>('Overview');
  const [data,setData] = useState<State>(EMPTY);
  const [apiStatus,setApiStatus] = useState<'checking'|'online'|'offline'>('checking');
  const [loading,setLoading] = useState(false);
  const [notice,setNotice] = useState('');
  const [query,setQuery] = useState('');
  const [typeFilter,setTypeFilter] = useState('all');
  const [categoryFilter,setCategoryFilter] = useState('all');
  const [dateFrom,setDateFrom] = useState('');
  const [dateTo,setDateTo] = useState('');
  const [alertStatusFilter,setAlertStatusFilter] = useState('all');
  const [mobileOpen,setMobileOpen] = useState(false);
  const [showAdd,setShowAdd] = useState(false);
  const [editingTx,setEditingTx] = useState<any>(null);
  const [budgetCategory,setBudgetCategory] = useState('Marketing');
  const [budgetAmount,setBudgetAmount] = useState('');
  const [importSummary,setImportSummary] = useState('');
  const [pendingFile,setPendingFile] = useState<File|null>(null);
  const [importPreview,setImportPreview] = useState<any>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const [simRevenue,setSimRevenue] = useState(0);
  const [simExpense,setSimExpense] = useState(0);
  const [simCost,setSimCost] = useState(0);
  const [simulation,setSimulation] = useState<any>(null);
  const [question,setQuestion] = useState('');
  const [chat,setChat] = useState<{role:'user'|'assistant';text:string;evidence?:any[]}[]>([
    {role:'assistant',text:'I can analyse the current workspace ledger. Ask about revenue, expenses, profit, vendors, or review signals.'}
  ]);
  const [newTx,setNewTx] = useState({date:new Date().toISOString().slice(0,10),description:'',vendor:'',category:'Operations',amount:'',type:'expense',currency:'USD'});

  const notify = (message:string) => { setNotice(message); window.setTimeout(()=>setNotice(''),3500); };
  const loadData = async (silent=false) => {
    if (!silent) setLoading(true);
    const paths = [
      '/api/v1/overview','/api/v1/transactions','/api/v1/expenses','/api/v1/revenue','/api/v1/comparison','/api/v1/data-quality','/api/v1/budgets','/api/v1/leaks',
      '/api/v1/anomalies','/api/v1/forecast','/api/v1/health-score','/api/v1/recommendations',
      '/api/v1/vendors','/api/v1/subscriptions','/api/v1/alerts'
    ];
    const results = await Promise.allSettled(paths.map(path=>apiGet<any>(path)));
    const ok = results[0].status === 'fulfilled' && results[1].status === 'fulfilled';
    if (ok) {
      const value = (i:number) => results[i].status === 'fulfilled' ? results[i].value : null;
      const transactions = value(1)?.transactions || [];
      setData({
        overview:value(0),transactions,expenses:value(2),revenue:value(3),comparison:value(4),quality:value(5),budgets:value(6),leaks:value(7)?.signals || [],
        anomalies:value(8),forecast:value(9),health:value(10),recommendations:value(11)?.recommendations || [],
        vendors:value(12)?.vendors || [],subscriptions:value(13)?.subscriptions || [],alerts:value(14)?.alerts || []
      });
      setApiStatus('online');
    } else {
      setApiStatus('offline');
      setData(prev=>({...prev,transactions:prev.transactions.length?prev.transactions:demoRows}));
    }
    if (!silent) setLoading(false);
  };
  useEffect(()=>{ void loadData(); },[]);
  const rows = data.transactions;
  const currency = data.overview?.currency || 'USD';
  const totals = useMemo(()=>rows.reduce((a,r)=>{if(r.type==='income')a.income+=Number(r.amount);else a.expenses+=Number(r.amount);return a;},{income:0,expenses:0}),[rows]);
  const filteredRows = useMemo(()=>rows.filter(r=>{
    const q=[r.id,r.description,r.vendor,r.category].join(' ').toLowerCase();
    return q.includes(query.toLowerCase()) && (typeFilter==='all'||r.type===typeFilter) && (categoryFilter==='all'||r.category===categoryFilter) && (!dateFrom||r.date>=dateFrom) && (!dateTo||r.date<=dateTo);
  }),[rows,query,typeFilter]);
  const go = (next:Page) => {setPage(next);setMobileOpen(false);setQuery('');};
  const importFile = async (file?:File) => {
    if (!file) return;
    try {
      const preview = await apiUpload<any>('/api/v1/import/preview',file);
      setPendingFile(file);
      setImportPreview(preview);
    } catch (e) { notify(`Import preview failed: ${String(e)}. Check the file format and local API.`); }
    finally { if(fileRef.current) fileRef.current.value=''; }
  };
  const confirmImport = async () => {
    if (!pendingFile) return;
    try {
      const result = await apiUpload<any>('/api/v1/import',pendingFile);
      const errors = result.errors?.length || 0;
      setImportSummary(`${result.inserted} transactions imported · ${result.duplicates_already_in_workspace + result.duplicates_within_file} duplicates · ${errors} invalid rows`);
      setPendingFile(null);setImportPreview(null);
      notify(`Import processed: ${result.inserted} new transactions added.`);
      await loadData(true);
    } catch (e) { notify(`Import failed: ${String(e)}`); }
  };
  const download = async (format:'csv'|'pdf') => {
    try { await apiDownload(`/api/v1/reports?format=${format}`,`leaklens-report.${format}`); notify(`${format.toUpperCase()} report downloaded.`); }
    catch(e) { notify(`Report export failed: ${String(e)}`); }
  };
  const changeAlert = async (id:string,status:string) => {
    try { await apiPatch(`/api/v1/alerts/${id}`,{status}); await loadData(true); notify(`Alert marked ${statusText(status).toLowerCase()}.`); }
    catch(e) { notify(`Could not update alert: ${String(e)}`); }
  };
  const addTransaction = async (event:FormEvent) => {
    event.preventDefault();
    try {
      await apiPost('/api/v1/transactions',{...newTx,amount:Number(newTx.amount)});
      setShowAdd(false);setNewTx(v=>({...v,description:'',vendor:'',amount:''}));
      await loadData(true);notify('Transaction added.');
    } catch(e) { notify(`Could not add transaction: ${String(e)}`); }
  };
  const runSimulation = async () => {
    try { setSimulation(await apiPost('/api/v1/simulate',{revenue_change_pct:simRevenue,expense_change_pct:simExpense,one_off_cost:simCost})); }
    catch(e) { notify(`Simulation unavailable: ${String(e)}`); }
  };
  const saveBudget = async (event:FormEvent) => {
    event.preventDefault();
    try { await apiPut('/api/v1/budgets',{category:budgetCategory,monthly_amount:Number(budgetAmount),currency}); setBudgetAmount(''); await loadData(true); notify('Category budget saved.'); }
    catch(e) { notify(`Could not save budget: ${String(e)}`); }
  };
  const beginEdit = (row:any) => setEditingTx({...row,amount:String(row.amount)});
  const saveEdit = async (event:FormEvent) => {
    event.preventDefault();
    if(!editingTx)return;
    const {id,source,...payload}=editingTx;
    try { await apiPut(`/api/v1/transactions/${id}`,{...payload,amount:Number(payload.amount)}); setEditingTx(null); await loadData(true); notify('Transaction updated.'); }
    catch(e) { notify(`Could not update transaction: ${String(e)}`); }
  };
  const removeTransaction = async (id:string) => {
    if(!window.confirm('Delete this transaction from the workspace ledger?'))return;
    try { await apiDelete(`/api/v1/transactions/${id}`); await loadData(true); notify('Transaction deleted.'); }
    catch(e) { notify(`Could not delete transaction: ${String(e)}`); }
  };
  const ask = async (event:FormEvent) => {
    event.preventDefault();const q=question.trim();if(!q)return;
    setChat(v=>[...v,{role:'user',text:q}]);setQuestion('');
    try { const answer=await apiPost<any>('/api/v1/assistant',{question:q});setChat(v=>[...v,{role:'assistant',text:answer.answer,evidence:answer.evidence}]); }
    catch(e) { setChat(v=>[...v,{role:'assistant',text:`I couldn't reach the LeakLens API. ${String(e)}`}]); }
  };
  const openFile = () => fileRef.current?.click();

  return <div className="shell">
    <aside className={`sidebar ${mobileOpen?'open':''}`}>
      <div className="brand"><div className="brand-mark"><ScanEye size={19}/></div><span>leak<span>lens</span><sup>®</sup></span><button className="mobile-close" onClick={()=>setMobileOpen(false)} aria-label="Close navigation"><X size={17}/></button></div>
      <div className="workspace"><div className="workspace-avatar">N</div><div><b>Northstar Studio</b><small>Local workspace · No account</small></div><ChevronDown size={15}/></div>
      {['WORKSPACE','INTELLIGENCE','MANAGE'].map(group=><div className="nav-group" key={group}><label>{group}</label>{NAV.filter(n=>n.group===group).map(n=><button key={n.label} className={`nav-link ${page===n.label?'selected':''}`} onClick={()=>go(n.label)}><n.icon size={17}/><span>{n.label}</span>{n.label==='Alerts centre'&&data.alerts.filter(a=>a.status==='open').length>0&&<i>{data.alerts.filter(a=>a.status==='open').length}</i>}</button>)}</div>)}
      <div className="side-bottom"><div className="side-promo"><div className="promo-icon"><Sparkles size={15}/></div><b>Find your next leak.</b><p>Turn financial noise into a clearer signal.</p><button onClick={()=>go('Leak detection')}>Explore intelligence <ArrowRight size={14}/></button></div><div className="profile"><div className="workspace-avatar">LL</div><div><b>LeakLens workspace</b><small>{apiStatus==='online'?'API connected':'Local preview mode'}</small></div><i className={apiStatus==='online'?'online':'offline'}/></div></div>
    </aside>
    {mobileOpen&&<button className="scrim" aria-label="Close menu" onClick={()=>setMobileOpen(false)}/>}
    <main className="main">
      <header className="topbar"><div className="crumb"><button className="mobile-trigger" onClick={()=>setMobileOpen(true)} aria-label="Open menu"><Menu size={18}/></button>Workspace <span>/</span> <b>{page}</b></div><div className="top-actions"><span className={`demo-status ${apiStatus}`}><i/>{apiStatus==='online'?'Local API connected':apiStatus==='checking'?'Connecting…':'API offline · demo preview'}</span><button className="icon-btn" aria-label="Refresh data" onClick={()=>loadData()}><RefreshCw size={16}/></button><div className="user-avatar">LL</div></div></header>
      <section className="content">
        <AnimatePresence mode="wait">
          {page==='Overview'&&<motion.div key={page} initial={{opacity:0,y:10}} animate={{opacity:1,y:0}} exit={{opacity:0}} className="stack">
            <Heading eyebrow="FINANCIAL OVERVIEW" title={<>See the bigger <em>picture.</em></>} subtitle="Your financial pulse, without the noise." actions={<><button className="btn secondary" onClick={()=>download('csv')}><Download size={15}/>Export data</button><button className="btn primary" onClick={openFile}><FileUp size={15}/>Import transactions</button></>}/>
            {importSummary&&<div className="import-note"><ShieldCheck size={15}/>{importSummary}</div>}
            {Object.keys(data.overview?.other_currencies||{}).length>1&&<div className="warning-note"><AlertTriangle size={15}/> This workspace contains multiple currencies. Headline totals and financial models use {currency} only; other currencies are not converted or combined.</div>}
            {apiStatus==='offline'&&<div className="warning-note"><AlertTriangle size={15}/> The API is offline. The screen is showing preview transactions; calculations, imports and intelligence require the backend to be running.</div>}
            <div className="metrics">
              <Metric label="Total revenue" value={fmt(data.overview?.revenue ?? totals.income,currency)} trend={data.overview?'▲ '+data.overview.profit_margin+'% margin':'Preview'} note="recorded income" icon={ArrowUpRight}/>
              <Metric label="Total expenses" value={fmt(data.overview?.expenses ?? totals.expenses,currency)} trend={data.overview?data.overview.transaction_count+' transactions':'Preview'} note="recorded outflow" icon={Wallet}/>
              <Metric label="Net movement" value={fmt(data.overview?.net ?? totals.income-totals.expenses,currency)} trend={data.overview?.net>=0?'Positive':'Negative'} note="revenue less expenses" icon={TrendingUp}/>
              <Metric label="Potential leak exposure" value={fmt(data.leaks.reduce((s,x)=>s+(x.estimated_exposure||0),0),currency)} trend={data.leaks.length+' signals'} note="requires human review" icon={ScanEye}/>
            </div>
            <div className="signal-banner"><div className="signal-icon"><Sparkles size={20}/></div><div><label>LEAKLENS SIGNAL <i>LIVE ANALYSIS</i></label><b>{data.leaks[0]?.title || 'Your financial data is ready for analysis.'}</b><p>{data.leaks[0]?.detail || 'Import transactions to uncover unusual spending, cost patterns and cash-flow insights.'}</p></div><button onClick={()=>go('Leak detection')}>Investigate signals <ArrowRight size={15}/></button><div className="orbit one"/><div className="orbit two"/></div>
            <div className="charts">
              <section className="panel"><Panel title="Cash flow overview" sub="Monthly income vs. expenditure" right={<span className="live-label">LEDGER DATA</span>}/><div className="legend"><span><i className="lime-dot"/>Inflow</span><span><i className="white-dot"/>Outflow</span></div><div className="chart">{data.overview?.monthly?.length?<ResponsiveContainer width="100%" height="100%"><AreaChart data={data.overview.monthly}><defs><linearGradient id="incomeFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#C6F432" stopOpacity={.22}/><stop offset="100%" stopColor="#C6F432" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#292B29" strokeDasharray="3 5" vertical={false}/><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fill:'#858980',fontSize:10}}/><YAxis axisLine={false} tickLine={false} tick={{fill:'#858980',fontSize:10}}/><Tooltip contentStyle={{background:'#171817',border:'1px solid #343730',borderRadius:9,color:'#fff'}} formatter={(v:number|string)=>fmt(Number(v),currency)}/><Area dataKey="income" type="monotone" stroke="#C6F432" strokeWidth={2.5} fill="url(#incomeFill)"/><Area dataKey="expenses" type="monotone" stroke="#E7E9E1" strokeWidth={1.8} fill="#ffffff0b"/></AreaChart></ResponsiveContainer>:<Empty text="Monthly analytics will appear when the API connects and records are loaded."/>}</div><div className="chart-foot"><span>{data.overview?.transaction_count||0} recorded transactions · {currency}</span><b>Data-backed analysis</b></div></section>
              <section className="panel"><Panel title="Where it goes" sub="Expense category distribution" right={<button className="link-btn" onClick={()=>go('Expense intelligence')}>Details <ArrowRight size={13}/></button>}/><div className="donut">{data.overview?.categories?.length?<ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={data.overview.categories} dataKey="value" nameKey="name" innerRadius={63} outerRadius={86} paddingAngle={3} stroke="none">{data.overview.categories.map((d:any,i:number)=><Cell key={d.name} fill={['#C6F432','#FFFFFF','#8B8F82','#55585A','#FFB84D'][i%5]}/>)}</Pie><Tooltip contentStyle={{background:'#171817',border:'1px solid #343730',borderRadius:9,color:'#fff'}} formatter={(v:number|string)=>fmt(Number(v),currency)}/></PieChart></ResponsiveContainer>:<Empty text="No expense categories yet."/>}<div className="donut-label"><b>{data.overview?.categories?.length?data.overview.categories.length:'—'}</b><small>CATEGORIES</small></div></div><div className="mix-legend">{(data.overview?.categories||[]).slice(0,6).map((e:any,i:number)=><div key={e.name}><span><i style={{background:['#C6F432','#FFFFFF','#8B8F82','#55585A','#FFB84D'][i%5]}}/>{e.name}</span><b>{e.share}%</b></div>)}</div></section>
            </div>
            <div className="lower"><section className="panel"><Panel title="Recent transactions" sub="Latest activity across this workspace" right={<button className="link-btn" onClick={()=>go('Transactions')}>All transactions <ArrowRight size={13}/></button>}/><TransactionTable rows={rows.slice(0,6)} currency={currency}/></section><section className="panel"><Panel title="Signals to review" sub="Evidence-led indicators" right={<span className="open-count">{data.leaks.length} OPEN</span>}/>{data.leaks.slice(0,4).map(a=><AlertRow key={a.id} item={a} currency={currency} onStatus={changeAlert}/>) }{!data.leaks.length&&<Empty text="No rule-based signals currently require review."/>}<button className="link-btn all-alerts" onClick={()=>go('Alerts centre')}>Open alerts centre <ArrowRight size={13}/></button></section></div>
          </motion.div>}
          {page==='Transactions'&&<motion.div key={page} initial={{opacity:0,y:10}} animate={{opacity:1,y:0}} className="stack"><Heading eyebrow="LEDGER MANAGEMENT" title={<>Every number has a <em>story.</em></>} subtitle="Search, filter, import and add business transactions." actions={<><button className="btn secondary" onClick={()=>setShowAdd(true)}><Plus size={15}/>Add transaction</button><button className="btn primary" onClick={openFile}><FileUp size={15}/>Import CSV / Excel</button></>}/><div className="toolbar"><div className="search"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search transactions, vendors, categories…"/></div><select value={typeFilter} onChange={e=>setTypeFilter(e.target.value)}><option value="all">All types</option><option value="income">Income</option><option value="expense">Expenses</option></select><select value={categoryFilter} onChange={e=>setCategoryFilter(e.target.value)}><option value="all">All categories</option>{Array.from(new Set(rows.map(r=>r.category))).sort().map(category=><option key={category} value={category}>{category}</option>)}</select><label className="date-filter">From<input type="date" value={dateFrom} onChange={e=>setDateFrom(e.target.value)}/></label><label className="date-filter">To<input type="date" value={dateTo} min={dateFrom||undefined} onChange={e=>setDateTo(e.target.value)}/></label><button className="mini-action" onClick={()=>{setQuery('');setTypeFilter('all');setCategoryFilter('all');setDateFrom('');setDateTo('');}}>Clear</button><span className="row-count">{filteredRows.length} records</span></div><section className="panel"><TransactionTable rows={filteredRows} currency={currency} onEdit={beginEdit} onDelete={removeTransaction}/></section></motion.div>}
          {page==='Expense intelligence'&&<ModuleFrame page={page} kicker="SPEND ANALYTICS"><div className="panel"><Panel title="Category budgets" sub="Set monthly targets and compare them with recorded month-to-date spend"/><form className="budget-form" onSubmit={saveBudget}><label>Category<input value={budgetCategory} onChange={e=>setBudgetCategory(e.target.value)} required maxLength={100}/></label><label>Monthly budget ({currency})<input type="number" min="0" step="0.01" value={budgetAmount} onChange={e=>setBudgetAmount(e.target.value)} required/></label><button className="btn primary" type="submit">Save budget <Plus size={14}/></button></form><BudgetList budgets={data.budgets?.budgets||[]} currency={currency}/></div><div className="metrics compact"><Metric label="Total expense" value={fmt(data.expenses?.total||0,currency)} trend="Recorded" note="all imported expense rows" icon={Wallet}/><Metric label="Fixed cost estimate" value={fmt(data.expenses?.fixed_estimate||0,currency)} trend="Recurring patterns" note="heuristic estimate" icon={RefreshCw}/><Metric label="Variable cost estimate" value={fmt(data.expenses?.variable_estimate||0,currency)} trend="Remaining expense" note="not a budget classification" icon={Activity}/></div><section className="panel"><Panel title="Category spend" sub="Actual ledger amounts and share"/><RankTable rows={data.expenses?.categories||[]} nameKey="name" valueKey="spend" shareKey="share" currency={currency}/></section><section className="panel"><Panel title="Recurring expenditure" sub="Inferred from repeated vendor charges"/><RankTable rows={data.expenses?.recurring||[]} nameKey="vendor" valueKey="median_amount" shareKey="occurrences" currency={currency} suffix=" occurrences"/></section></ModuleFrame>}
          {page==='Revenue intelligence'&&<ModuleFrame page={page} kicker="REVENUE & CUSTOMER INTELLIGENCE"><div className="metrics compact"><Metric label="Recorded revenue" value={fmt(data.revenue?.total||0,currency)} trend="Ledger total" note="income transactions" icon={ArrowUpRight}/><Metric label="Revenue sources" value={String(data.revenue?.sources?.length||0)} trend="Categories" note="source breakdown" icon={Activity}/><Metric label="Paying counterparties" value={String(data.revenue?.counterparties?.length||0)} trend="Vendor/payee field" note="customer identity depends on source data" icon={Wallet}/></div><section className="panel"><Panel title="Revenue by source" sub="Income categories from transaction records"/><RankTable rows={data.revenue?.sources||[]} nameKey="name" valueKey="revenue" shareKey="share" currency={currency}/></section><section className="panel"><Panel title="Counterparty revenue" sub="Income grouped by the uploaded vendor/payee field"/><RankTable rows={data.revenue?.counterparties||[]} nameKey="name" valueKey="revenue" shareKey="share" currency={currency}/></section><section className="panel"><Panel title="Period comparison" sub="Latest two months represented in the ledger"/>{data.comparison?.available?<div className="scenario-results"><div><span>{data.comparison.current_period} revenue</span><b>{fmt(data.comparison.current.revenue,currency)}</b><small>{data.comparison.change_pct.revenue===null?'No prior baseline':data.comparison.change_pct.revenue+'% vs previous month'}</small></div><div><span>{data.comparison.current_period} expenses</span><b>{fmt(data.comparison.current.expenses,currency)}</b><small>{data.comparison.change_pct.expenses===null?'No prior baseline':data.comparison.change_pct.expenses+'% vs previous month'}</small></div><div><span>{data.comparison.current_period} net</span><b>{fmt(data.comparison.current.net,currency)}</b><small>{data.comparison.note}</small></div></div>:<Empty text={data.comparison?.reason||'Not enough months to compare.'}/>}</section></ModuleFrame>}
          {page==='Data quality'&&<ModuleFrame page={page} kicker="DATA QUALITY & VALIDATION"><div className="health-score"><div className="score-number"><b>{data.quality?.quality_score??'—'}</b><small>/ 100</small></div><div><span className="health-label">DATA COMPLETENESS HEURISTIC</span><h3>{data.quality?.transaction_count||0} transactions reviewed</h3><p>{data.quality?.note||'Quality checks run on normalized ledger rows.'}</p></div></div><div className="model-summary"><div><span>TRANSACTIONS</span><b>{data.quality?.transaction_count||0}</b></div><div><span>CURRENCIES</span><b>{data.quality?.currency_count||0}</b></div><div><span>DATA SOURCES</span><b>{Object.keys(data.quality?.source_counts||{}).length}</b></div></div><section className="panel"><Panel title="Validation findings" sub="Missing fields and invalid values"/></section>{(data.quality?.issues||[]).map((issue:any)=><div className="anomaly-row" key={issue.field}><div className={`risk-dot ${issue.severity}`}/><div className="anomaly-main"><b>{issue.field}</b><p>{issue.message}</p></div><strong>{issue.count} rows</strong></div>)}{!data.quality?.issues?.length&&<Empty text="No missing required fields or invalid amounts were detected."/>}<p className="module-intro">{data.quality?.duplicate_policy}</p></ModuleFrame>}
          {page==='Leak detection'&&<ModuleFrame page={page} kicker="RULE-BASED LEAK DETECTION"><p className="module-intro">Signals are potential issues to investigate, not confirmed losses or fraud. Each signal includes a rule explanation and source evidence.</p>{data.leaks.map(s=><SignalCard key={s.id} item={s} currency={currency} onStatus={changeAlert}/>)}{!data.leaks.length&&<Empty text="No rule-based leak indicators were found in the current ledger."/>}</ModuleFrame>}
          {page==='Anomaly intelligence'&&<ModuleFrame page={page} kicker="MACHINE LEARNING"><div className="model-summary"><div><span>MODEL</span><b>{data.anomalies?.model||'Isolation Forest'}</b></div><div><span>EXPENSE SAMPLE</span><b>{data.anomalies?.sample_size||0}</b></div><div><span>FLAGGED PATTERNS</span><b>{data.anomalies?.flagged_count||0}</b></div></div><p className="module-intro">{data.anomalies?.note||data.anomalies?.reason||'Model output becomes available once enough transaction history is available.'}</p>{(data.anomalies?.results||[]).map((r:any)=><div className="anomaly-row" key={r.transaction.id}><div className={`risk-dot ${r.severity}`}/><div className="anomaly-main"><b>{r.transaction.description}</b><p>{r.explanation}</p><small>{r.transaction.vendor} · {r.transaction.date}</small></div><div className="anomaly-score"><b>{r.score.toFixed(1)}</b><small>ANOMALY SCORE</small><small>IF {r.model_scores?.isolation_forest_percentile??'—'} · LOF {r.model_scores?.local_outlier_factor_percentile??'—'}</small></div><strong>{fmt(r.transaction.amount,currency)}</strong></div>)}</ModuleFrame>}
          {page==='Forecasting'&&<ModuleFrame page={page} kicker="PREDICTIVE INTELLIGENCE"><p className="module-intro">{data.forecast?.available?data.forecast.uncertainty:data.forecast?.reason||'Forecasting requires enough monthly transaction history.'}</p>{data.forecast?.available?<><div className="model-summary"><div><span>MODEL</span><b>{data.forecast.model}</b></div><div><span>LINEAR TREND MAE</span><b>{data.forecast.backtest_mae===null?'Not available':fmt(data.forecast.backtest_mae,currency)}</b></div><div><span>VS NAIVE BASELINE</span><b>{data.forecast.backtest_improvement_pct===null?'—':`${data.forecast.backtest_improvement_pct}%`}</b></div></div><p className="module-intro">Rolling origins: {data.forecast.backtest_periods||0} · Trend MAE: {data.forecast.backtest_mae===null?'not available':fmt(data.forecast.backtest_mae,currency)} · Naive MAE: {data.forecast.backtest_naive_mae===null?'not available':fmt(data.forecast.backtest_naive_mae,currency)}. {data.forecast.backtest_method} {data.forecast.selected_model_by_metric&&`Selected revenue model: ${data.forecast.selected_model_by_metric.income}; selected expense model: ${data.forecast.selected_model_by_metric.expenses}.`}</p><section className="panel"><Panel title="Revenue and expense outlook" sub="Historical actuals followed by the best eligible backtested baseline"/><div className="chart forecast-chart"><ResponsiveContainer width="100%" height="100%"><LineChart data={[...(data.forecast.history||[]).map((x:any)=>({...x,incomeForecast:null,expenseForecast:null})),...(data.forecast.forecast||[]).map((x:any)=>({month:x.month,income:null,expenses:null,incomeForecast:x.income,expenseForecast:x.expenses}))]}><CartesianGrid stroke="#292B29" strokeDasharray="3 5" vertical={false}/><XAxis dataKey="month" tick={{fill:'#858980',fontSize:10}} axisLine={false} tickLine={false}/><YAxis tick={{fill:'#858980',fontSize:10}} axisLine={false} tickLine={false}/><Tooltip contentStyle={{background:'#171817',border:'1px solid #343730',borderRadius:9,color:'#fff'}}/><Legend/><Line connectNulls dataKey="income" name="Actual revenue" stroke="#C6F432" strokeWidth={2}/><Line connectNulls dataKey="expenses" name="Actual expenses" stroke="#FFFFFF" strokeWidth={2}/><Line connectNulls dataKey="incomeForecast" name="Forecast revenue" stroke="#C6F432" strokeDasharray="5 5"/><Line connectNulls dataKey="expenseForecast" name="Forecast expenses" stroke="#FFFFFF" strokeDasharray="5 5"/></LineChart></ResponsiveContainer></div></section><RankTable rows={data.forecast.forecast||[]} nameKey="month" valueKey="net" currency={currency}/></>:<Empty text={data.forecast?.reason||'Forecast is unavailable.'}/>}</ModuleFrame>}
          {page==='Business health'&&<ModuleFrame page={page} kicker="FINANCIAL HEALTH INDEX">{data.health?.available?<><div className="health-score"><div className="score-number"><b>{data.health.score}</b><small>/ 100</small></div><div><span className="health-label">{data.health.label}</span><h3>Financial health snapshot</h3><p>{data.health.methodology}</p></div></div><div className="health-grid">{data.health.components.map((c:any)=><div className="health-component" key={c.name}><div><b>{c.name}</b><strong>{c.score}/100</strong></div><div className="progress"><i style={{width:`${c.score}%`}}/></div><p>{c.basis}</p><small>Weight: {c.weight}%</small></div>)}</div><section className="panel"><Panel title="Health score history" sub="One snapshot is stored per day when the score is viewed"/>{data.health.history?.length>0?<><div className="chart health-history-chart"><ResponsiveContainer width="100%" height="100%"><LineChart data={data.health.history}><CartesianGrid stroke="#292B29" strokeDasharray="3 5" vertical={false}/><XAxis dataKey="date" tick={{fill:'#858980',fontSize:9}} axisLine={false} tickLine={false}/><YAxis domain={[0,100]} tick={{fill:'#858980',fontSize:10}} axisLine={false} tickLine={false}/><Tooltip contentStyle={{background:'#171817',border:'1px solid #343730',borderRadius:9,color:'#fff'}}/><Line type="monotone" dataKey="score" name="Health score" stroke="#C6F432" strokeWidth={2.5} dot={{fill:'#C6F432',r:3}}/></LineChart></ResponsiveContainer></div><p className="module-intro">History begins from the date snapshots are enabled; previous dates are not reconstructed.</p></>:<Empty text="The first score snapshot will appear here. Revisit the dashboard on later days to build a trend."/>}</section></>:<Empty text={data.health?.reason||'Health score is not yet available.'}/>}</ModuleFrame>}
          {page==='Recommendations'&&<ModuleFrame page={page} kicker="ACTION INTELLIGENCE"><p className="module-intro">Suggestions are linked to observed records and potential exposure. Estimated exposure is not guaranteed savings.</p>{data.recommendations.map((r:any)=><div className="recommendation" key={r.id}><div className={`priority ${r.priority}`}>{r.priority}</div><div><h3>{r.title}</h3><p>{r.action}</p><small>{r.evidence}</small></div><div className="recommend-value"><b>{r.potential_savings?fmt(r.potential_savings,currency):'Review'}</b><small>{r.savings_type}</small></div></div>)}{!data.recommendations.length&&<Empty text="No recommendations are available yet."/>}</ModuleFrame>}
          {page==='What-if simulator'&&<ModuleFrame page={page} kicker="SCENARIO PLANNING"><p className="module-intro">Adjust assumptions to see how an average of the last three recorded calendar months could change. This is a scenario calculator, not a cash forecast.</p><div className="simulator"><SliderField label="Revenue change" value={simRevenue} onChange={setSimRevenue} min={-50} max={100}/><SliderField label="Expense change" value={simExpense} onChange={setSimExpense} min={-50} max={100}/><label className="field-label">One-off cost ({currency})<input type="number" min="0" value={simCost} onChange={e=>setSimCost(Number(e.target.value))}/></label><button className="btn primary" onClick={runSimulation}><SlidersHorizontal size={15}/>Run scenario</button></div>{simulation&&<div className="scenario-results"><div><span>BASELINE NET</span><b>{fmt(simulation.baseline.net,currency)}</b></div><div><span>SCENARIO NET</span><b>{fmt(simulation.scenario.net,currency)}</b></div><div><span>NET CHANGE</span><b className={simulation.net_change>=0?'positive':'negative'}>{fmt(simulation.net_change,currency)}</b></div></div>}</ModuleFrame>}
          {page==='Vendor intelligence'&&<ModuleFrame page={page} kicker="SUPPLIER ANALYTICS"><p className="module-intro">Vendor totals are calculated from recorded expense transactions in the selected workspace currency.</p><RankTable rows={data.vendors} nameKey="name" valueKey="spend" shareKey="share" currency={currency}/></ModuleFrame>}
          {page==='Subscription intelligence'&&<ModuleFrame page={page} kicker="RECURRING COST INTELLIGENCE"><p className="module-intro">Recurring charges are inferred from repeated vendor payments. Contract status and actual product usage are not available from ledger data alone.</p>{data.subscriptions.map((s:any)=><div className="anomaly-row" key={s.vendor}><div className="recurring-mark"><RefreshCw size={16}/></div><div className="anomaly-main"><b>{s.vendor}</b><p>{s.occurrences} observed transactions · median recurring amount</p></div><strong>{fmt(s.median_amount,currency)}</strong><span className="status">Inferred pattern</span></div>)}{!data.subscriptions.length&&<Empty text="No recurring payment patterns have been identified yet."/>}</ModuleFrame>}
          {page==='Alerts centre'&&<ModuleFrame page={page} kicker="RISK & REVIEW QUEUE"><div className="filter-line"><span>{data.alerts.length} total signals</span><select value={alertStatusFilter} onChange={e=>setAlertStatusFilter(e.target.value)}><option value="all">All statuses</option><option value="open">Open</option><option value="reviewed">Reviewed</option><option value="dismissed">Dismissed</option><option value="resolved">Resolved</option></select></div>{data.alerts.filter(a=>alertStatusFilter==='all'||a.status===alertStatusFilter).map(a=><SignalCard key={a.id} item={a} currency={currency} onStatus={changeAlert} showStatus/>)}{!data.alerts.length&&<Empty text="No current alerts."/>}</ModuleFrame>}
          {page==='AI assistant'&&<ModuleFrame page={page} kicker="LEAKLENS ASSISTANT"><p className="module-intro">The current assistant is deterministic and answers from the workspace ledger. It does not send your financial data to an external AI provider.</p><div className="chat-window">{chat.map((m,i)=><div className={`chat-message ${m.role}`} key={i}><div className="chat-avatar">{m.role==='assistant'?<Sparkles size={15}/>:<Wallet size={15}/>}</div><div><p>{m.text}</p>{m.evidence && m.evidence.length>0 && <details><summary>View supporting evidence ({m.evidence.length})</summary><pre>{JSON.stringify(m.evidence,null,2)}</pre></details>}</div></div>)}</div><form className="chat-form" onSubmit={ask}><input value={question} onChange={e=>setQuestion(e.target.value)} placeholder="Ask about expenses, revenue, vendors or risks…"/><button className="btn primary" type="submit">Ask <ArrowRight size={15}/></button></form><div className="prompt-chips">{['Which vendor costs the most?','Why are expenses increasing?','Where are unusual expenses?'].map(q=><button key={q} onClick={()=>setQuestion(q)}>{q}</button>)}</div></ModuleFrame>}
          {page==='Reports'&&<ModuleFrame page={page} kicker="REPORTING STUDIO"><p className="module-intro">Generate exports from the same validated ledger used by your analytics. CSV contains transaction detail; PDF contains a financial summary and monthly trend table.</p><div className="report-grid"><div className="report-card"><FileDown size={23}/><h3>Transaction export</h3><p>Download all workspace ledger rows as a CSV file.</p><button className="btn secondary" onClick={()=>download('csv')}>Download CSV <Download size={14}/></button></div><div className="report-card"><FileDown size={23}/><h3>Financial summary</h3><p>Download a printable PDF summary with totals and monthly trends.</p><button className="btn primary" onClick={()=>download('pdf')}>Download PDF <Download size={14}/></button></div></div></ModuleFrame>}
          {page==='Settings'&&<ModuleFrame page={page} kicker="WORKSPACE PREFERENCES"><div className="settings-list"><div><div><b>Authentication</b><p>Disabled in v1.0 as requested. The app opens directly into a local workspace.</p></div><span className="status">No sign-in</span></div><div><div><b>Workspace data</b><p>Transactions are stored in the API's local SQLite database. The default demo ledger is seeded on first run.</p></div><span className="status">Local database</span></div><div><div><b>Currency</b><p>Currency is inferred from imported transactions. Mixed currencies are not converted; analytics use the most common currency.</p></div><span className="status">{currency}</span></div><div><div><b>External AI services</b><p>Not connected. The assistant uses deterministic, explainable answers from ledger data.</p></div><span className="status">No API key</span></div></div><button className="btn secondary" onClick={()=>loadData()}><RefreshCw size={15}/>Refresh workspace data</button></ModuleFrame>}
        </AnimatePresence>
        {loading&&<div className="loading-bar"><i/></div>}
      </section>
      <footer className="footer"><span>LEAKLENS © 2026</span><span>FINANCIAL CLARITY, BY DESIGN <b>●</b> {apiStatus==='online'?'LOCAL API':'PREVIEW MODE'}</span></footer>
    </main>
    <input ref={fileRef} hidden type="file" accept=".csv,.xlsx,.xls,text/csv" onChange={e=>importFile(e.target.files?.[0])}/>
    <AnimatePresence>{notice&&<motion.div initial={{opacity:0,y:10}} animate={{opacity:1,y:0}} exit={{opacity:0}} className="toast"><ShieldCheck size={16}/>{notice}</motion.div>}</AnimatePresence>
    <AnimatePresence>{editingTx&&<div className="modal-backdrop"><motion.form initial={{opacity:0,y:12,scale:.98}} animate={{opacity:1,y:0,scale:1}} exit={{opacity:0}} className="add-modal" onSubmit={saveEdit}><div className="modal-heading"><div><span>LEDGER ENTRY</span><h2>Edit transaction</h2></div><button type="button" className="icon-btn" onClick={()=>setEditingTx(null)}><X size={16}/></button></div><label>Date<input type="date" required value={editingTx.date} onChange={e=>setEditingTx((v:any)=>({...v,date:e.target.value}))}/></label><label>Description<input required value={editingTx.description} onChange={e=>setEditingTx((v:any)=>({...v,description:e.target.value}))}/></label><label>Vendor<input required value={editingTx.vendor} onChange={e=>setEditingTx((v:any)=>({...v,vendor:e.target.value}))}/></label><div className="form-row"><label>Amount<input type="number" required min="0.01" step="0.01" value={editingTx.amount} onChange={e=>setEditingTx((v:any)=>({...v,amount:e.target.value}))}/></label><label>Type<select value={editingTx.type} onChange={e=>setEditingTx((v:any)=>({...v,type:e.target.value}))}><option value="expense">Expense</option><option value="income">Income</option></select></label></div><div className="form-row"><label>Category<input value={editingTx.category} onChange={e=>setEditingTx((v:any)=>({...v,category:e.target.value}))}/></label><label>Currency<input maxLength={3} value={editingTx.currency} onChange={e=>setEditingTx((v:any)=>({...v,currency:e.target.value.toUpperCase()}))}/></label></div><div className="modal-actions"><button type="button" className="btn secondary" onClick={()=>setEditingTx(null)}>Cancel</button><button type="submit" className="btn primary">Save changes <ArrowRight size={14}/></button></div></motion.form></div>}</AnimatePresence>
    <AnimatePresence>{importPreview&&pendingFile&&<div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget){setPendingFile(null);setImportPreview(null);}}}><motion.div initial={{opacity:0,y:12,scale:.98}} animate={{opacity:1,y:0,scale:1}} exit={{opacity:0}} className="import-modal"><div className="modal-heading"><div><span>DATA IMPORT · PREVIEW</span><h2>Review before importing</h2><p>{pendingFile.name} · {(pendingFile.size/1024).toFixed(1)} KB</p></div><button type="button" className="icon-btn" onClick={()=>{setPendingFile(null);setImportPreview(null);}}><X size={16}/></button></div><div className="import-stats"><div><b>{importPreview.valid_rows}</b><small>VALID ROWS</small></div><div><b>{importPreview.estimated_new_rows}</b><small>ESTIMATED NEW</small></div><div><b>{importPreview.duplicates_already_in_workspace+importPreview.duplicates_within_file}</b><small>DUPLICATES</small></div><div><b>{importPreview.errors?.length||0}</b><small>INVALID ROWS</small></div></div><div className="import-columns"><b>Detected columns</b><p>{Object.entries(importPreview.mapped_columns||{}).map(([key,value])=>`${key}: ${value}`).join(' · ')}</p></div><div className="import-preview-table"><b>First records</b><div className="table-scroll"><table><thead><tr><th>DATE</th><th>DESCRIPTION</th><th>VENDOR</th><th>CATEGORY</th><th>AMOUNT</th><th>TYPE</th></tr></thead><tbody>{(importPreview.preview||[]).map((row:any,i:number)=><tr key={i}><td>{row.date}</td><td>{row.description}</td><td>{row.vendor}</td><td>{row.category}</td><td>{fmt(row.amount,row.currency)}</td><td>{row.type}</td></tr>)}</tbody></table></div></div>{importPreview.errors?.length>0&&<details className="import-errors"><summary>View rejected rows ({importPreview.errors.length})</summary><pre>{JSON.stringify(importPreview.errors,null,2)}</pre></details>}<p className="module-intro">{importPreview.note}</p><div className="modal-actions"><button type="button" className="btn secondary" onClick={()=>{setPendingFile(null);setImportPreview(null);}}>Cancel</button><button type="button" className="btn primary" disabled={importPreview.estimated_new_rows===0} onClick={confirmImport}>Confirm import <ArrowRight size={14}/></button></div></motion.div></div>}</AnimatePresence>
    <AnimatePresence>{showAdd&&<div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setShowAdd(false);}}><motion.form initial={{opacity:0,y:12,scale:.98}} animate={{opacity:1,y:0,scale:1}} exit={{opacity:0}} className="add-modal" onSubmit={addTransaction}><div className="modal-heading"><div><span>LEDGER ENTRY</span><h2>Add transaction</h2></div><button type="button" className="icon-btn" onClick={()=>setShowAdd(false)}><X size={16}/></button></div><label>Date<input type="date" required value={newTx.date} onChange={e=>setNewTx(v=>({...v,date:e.target.value}))}/></label><label>Description<input required value={newTx.description} onChange={e=>setNewTx(v=>({...v,description:e.target.value}))}/></label><label>Vendor<input required value={newTx.vendor} onChange={e=>setNewTx(v=>({...v,vendor:e.target.value}))}/></label><div className="form-row"><label>Amount<input type="number" required min="0.01" step="0.01" value={newTx.amount} onChange={e=>setNewTx(v=>({...v,amount:e.target.value}))}/></label><label>Type<select value={newTx.type} onChange={e=>setNewTx(v=>({...v,type:e.target.value}))}><option value="expense">Expense</option><option value="income">Income</option></select></label></div><div className="form-row"><label>Category<input value={newTx.category} onChange={e=>setNewTx(v=>({...v,category:e.target.value}))}/></label><label>Currency<input maxLength={3} value={newTx.currency} onChange={e=>setNewTx(v=>({...v,currency:e.target.value.toUpperCase()}))}/></label></div><div className="modal-actions"><button type="button" className="btn secondary" onClick={()=>setShowAdd(false)}>Cancel</button><button type="submit" className="btn primary">Save transaction <ArrowRight size={14}/></button></div></motion.form></div>}</AnimatePresence>
  </div>;
}

function Heading({eyebrow,title,subtitle,actions}:{eyebrow:string;title:ReactNode;subtitle:string;actions?:ReactNode}) {return <div className="heading"><div><div className="eyebrow"><i/>{eyebrow}</div><h1>{title}</h1><p>{subtitle}</p></div>{actions&&<div className="heading-buttons">{actions}</div>}</div>;}
function Metric({label,value,trend,note,icon:Icon}:{label:string;value:string;trend:string;note:string;icon:any}) {return <article className="metric"><div className="metric-head"><span>{label}</span><i><Icon size={16}/></i></div><b className="metric-value">{value}</b><div className="metric-foot"><strong>{trend}</strong><span>{note}</span></div><div className="metric-orbit"/></article>;}
function Panel({title,sub,right}:{title:string;sub:string;right?:ReactNode}) {return <header className="panel-head"><div><h2>{title}</h2><p>{sub}</p></div>{right}</header>;}
function Empty({text}:{text:string}) {return <div className="empty">{text}</div>;}
function TransactionTable({rows,currency,onEdit,onDelete}:{rows:any[];currency:string;onEdit?:(row:any)=>void;onDelete?:(id:string)=>void}) {return <div className="table-scroll"><table><thead><tr><th>TRANSACTION</th><th>VENDOR</th><th>CATEGORY</th><th>DATE</th><th>AMOUNT</th><th>STATUS</th>{onEdit&&<th>ACTIONS</th>}</tr></thead><tbody>{rows.map(r=><tr key={r.id}><td><b>{r.description}</b><small>{r.id}</small></td><td>{r.vendor}</td><td><span className="category">{r.category}</span></td><td>{r.date}</td><td className={r.type==='income'?'income':'expense'}>{r.type==='income'?'+':'−'}{fmt(r.amount,r.currency||currency)}</td><td><span className="status"><i/>{r.source==='demo'?'Demo':r.source==='upload'?'Imported':'Recorded'}</span></td>{onEdit&&<td><div className="table-actions"><button aria-label={`Edit ${r.description}`} onClick={()=>onEdit(r)}><Pencil size={13}/></button><button aria-label={`Delete ${r.description}`} onClick={()=>onDelete?.(r.id)}><Trash2 size={13}/></button></div></td>}</tr>)}</tbody></table>{!rows.length&&<Empty text="No transactions match these filters."/>}</div>;}
function ModuleFrame({page,kicker,children}:{page:Page;kicker:string;children:ReactNode}) {return <motion.div key={page} initial={{opacity:0,y:8}} animate={{opacity:1,y:0}} className="stack"><Heading eyebrow={kicker} title={<>{page==='Leak detection'?'Find what slips through.':page==='Forecasting'?'Look around the corner.':page==='Business health'?'Know where you stand.':page==='Recommendations'?'Make your next move count.':page==='What-if simulator'?'Test the possibilities.':page==='AI assistant'?'Ask the ledger.':page==='Reports'?'Clarity you can carry.':page==='Alerts centre'?'Every signal, in one place.':page==='Expense intelligence'?'Understand every outflow.':page==='Vendor intelligence'?'Know your counterparties.':page==='Subscription intelligence'?'Keep recurring costs visible.':'See what stands out.'}</>} subtitle={page}/>{children}</motion.div>;}
function RankTable({rows,nameKey,valueKey,shareKey,currency,suffix=''}:{rows:any[];nameKey:string;valueKey:string;shareKey?:string;currency:string;suffix?:string}) {return <div className="rank-table">{rows.map((r,i)=><div className="rank-row" key={r[nameKey]||i}><span className="rank-index">{String(i+1).padStart(2,'0')}</span><div className="rank-name"><b>{r[nameKey]}</b>{shareKey&&<div className="rank-track"><i style={{width:`${Math.min(100,Number(r[shareKey])||0)}%`}}/></div>}</div><strong>{valueKey==='occurrences'?r[valueKey]+suffix:fmt(r[valueKey],currency)}</strong>{shareKey&&valueKey!=='occurrences'&&<small>{r[shareKey]}%</small>}</div>)}{!rows.length&&<Empty text="Not enough data for this view yet."/>}</div>;}
function AlertRow({item,currency,onStatus}:{item:any;currency:string;onStatus:(id:string,status:string)=>void}) {return <div className="alert-row"><div className={`alert-icon ${item.severity}`}><AlertTriangle size={15}/></div><div className="alert-copy"><b>{item.title}</b><p>{item.detail}</p><small>{item.severity} priority · {item.status||'open'}</small></div><strong>{item.estimated_exposure?fmt(item.estimated_exposure,currency):'—'}</strong><button className="mini-action" onClick={()=>onStatus(item.id,'reviewed')}>Review</button></div>;}
function SignalCard({item,currency,onStatus,showStatus=false}:{item:any;currency:string;onStatus:(id:string,status:string)=>void;showStatus?:boolean}) {return <section className="panel signal-detail"><div className={`alert-icon ${item.severity}`}><AlertTriangle size={17}/></div><div className="signal-detail-copy"><label>{(item.severity||'medium').toUpperCase()} PRIORITY · {item.kind||item.source||'SIGNAL'}</label><h3>{item.title}</h3><p>{item.detail}</p><small>{item.method||item.classification||'Evidence-led pattern'} · {item.evidence_count||item.evidence?.length||0} evidence records</small>{item.evidence?.length>0&&<details className="evidence"><summary>Inspect supporting evidence</summary><pre>{JSON.stringify(item.evidence,null,2)}</pre></details>}{item.history?.length>0&&<details className="evidence"><summary>View status history ({item.history.length})</summary><pre>{JSON.stringify(item.history,null,2)}</pre></details>}</div><div className="signal-side"><b>{item.source==='ml-ensemble'?fmt(item.amount_under_review||0,currency):item.estimated_exposure?fmt(item.estimated_exposure,currency):'Review'}</b><small>{item.source==='ml-ensemble'?'transaction amount under review':'potential exposure'}</small>{showStatus&&<span className="status">{statusText(item.status||'open')}</span>}<div className="signal-actions"><button className="btn secondary" onClick={()=>onStatus(item.id,'reviewed')}>Mark reviewed</button><button className="btn secondary" onClick={()=>onStatus(item.id,'dismissed')}>Dismiss</button><button className="btn secondary" onClick={()=>onStatus(item.id,'resolved')}>Resolve</button>{(item.status==='dismissed'||item.status==='resolved')&&<button className="btn secondary" onClick={()=>onStatus(item.id,'open')}>Reopen</button>}</div></div></section>;}
function SliderField({label,value,onChange,min,max}:{label:string;value:number;onChange:(n:number)=>void;min:number;max:number}) {return <label className="slider-field"><span>{label}<b>{value>0?'+':''}{value}%</b></span><input type="range" min={min} max={max} step="1" value={value} onChange={e=>onChange(Number(e.target.value))}/><small>{min}% <span>{max}%</span></small></label>;}

function BudgetList({budgets,currency}:{budgets:any[];currency:string}) {return <div className="budget-list">{budgets.map(b=><div className="budget-row" key={b.category}><div><b>{b.category}</b><small>{fmt(b.actual_mtd,currency)} actual · {fmt(b.budget,currency)} budget · {b.status}</small></div><strong>{fmt(b.remaining,currency)} left</strong><div className="progress"><i className={b.status==='over budget'?'over':''} style={{width:`${Math.min(100,b.budget?b.actual_mtd/b.budget*100:0)}%`}}/></div><small>Projected month-end: {fmt(b.projected_month_end,currency)}</small></div>)}{!budgets.length&&<Empty text="Add a category budget to see actual vs target and projected month-end spend."/>}</div>;}
